import { eventBus } from '../../core/EventBus';
import { parseAtlasText, type AtlasRegion, type ParsedAtlas } from '../../services/AtlasParser';
import type { SpineFileSet } from '../../types/spine';

export class AtlasInspectorPanel {
    element: HTMLElement;
    private searchInput!: HTMLInputElement;
    private regionList!: HTMLElement;
    private previewCanvas!: HTMLCanvasElement;
    private previewCtx!: CanvasRenderingContext2D;
    private detailPanel!: HTMLElement;
    private statsPanel!: HTMLElement;
    private atlasData: ParsedAtlas | null = null;
    private textureImages: Map<string, HTMLImageElement> = new Map();
    private selectedRegion: AtlasRegion | null = null;
    private usedRegionNames: Set<string> = new Set();
    private showUnusedOnly = false;
    private unusedFilterBtn!: HTMLButtonElement;

    private compareAtlases: Map<string, { atlas: ParsedAtlas; textures: SpineFileSet['textures'] }> = new Map();
    private isCompareMode = false;
    private activeAtlasProject = '';
    private projectSelectorRow!: HTMLElement;
    private projectSelector!: HTMLSelectElement;
    private compareSection!: HTMLElement;
    private compareSectionBody!: HTMLElement;

    constructor() {
        this.element = document.createElement('div');
        this.element.style.display = 'flex';
        this.element.style.flexDirection = 'column';
        this.build();

        eventBus.on('atlas:loaded', (data: { atlas: ParsedAtlas; textures: SpineFileSet['textures']; usedRegionNames?: Set<string>; projectName?: string }) => {
            if (data.projectName) {
                // Store as comparison project atlas
                this.compareAtlases.set(data.projectName, { atlas: data.atlas, textures: data.textures });
                this.updateProjectSelector();
                // If this is the currently active compare project (or first one), display it
                if (!this.isCompareMode) {
                    this.usedRegionNames = data.usedRegionNames ?? new Set();
                    this.setAtlasData(data.atlas, data.textures);
                } else if (!this.activeAtlasProject || this.activeAtlasProject === data.projectName) {
                    this.activeAtlasProject = data.projectName;
                    this.projectSelector.value = data.projectName;
                    this.usedRegionNames = new Set();
                    this.setAtlasData(data.atlas, data.textures);
                }
                if (this.isCompareMode) this.renderAtlasDiff();
            } else {
                // Single-mode atlas (no projectName)
                this.usedRegionNames = data.usedRegionNames ?? new Set();
                if (!this.isCompareMode) {
                    this.setAtlasData(data.atlas, data.textures);
                }
            }
        });

        eventBus.on('mode:change', (mode: string) => {
            this.isCompareMode = mode === 'comparison';
            this.projectSelectorRow.style.display = this.isCompareMode ? 'flex' : 'none';
            if (this.isCompareMode) {
                this.updateProjectSelector();
                // Show first compare atlas if available
                const firstEntry = this.compareAtlases.size > 0
                    ? this.compareAtlases.entries().next().value
                    : null;
                if (firstEntry) {
                    this.activeAtlasProject = firstEntry[0] as string;
                    this.projectSelector.value = this.activeAtlasProject;
                    this.usedRegionNames = new Set();
                    this.setAtlasData(firstEntry[1].atlas, firstEntry[1].textures);
                }
                this.renderAtlasDiff();
            }
        });

        eventBus.on('comparison:projects-changed', (projects: Array<{ name: string }>) => {
            const names = new Set(projects.map(p => p.name));
            for (const key of this.compareAtlases.keys()) {
                if (!names.has(key)) this.compareAtlases.delete(key);
            }
            this.updateProjectSelector();
            if (this.isCompareMode) this.renderAtlasDiff();
        });
    }

    private updateProjectSelector(): void {
        this.projectSelector.innerHTML = '';
        this.compareAtlases.forEach((_, name) => {
            const opt = document.createElement('option');
            opt.value = name;
            opt.textContent = name;
            this.projectSelector.appendChild(opt);
        });
        if (this.activeAtlasProject) {
            this.projectSelector.value = this.activeAtlasProject;
        }
    }

    private build(): void {
        // Stats overview (shown when atlas is loaded)
        this.statsPanel = document.createElement('div');
        this.statsPanel.style.padding = '4px 0';
        this.element.appendChild(this.statsPanel);

        // Preview canvas
        const previewWrap = document.createElement('div');
        previewWrap.style.position = 'relative';
        previewWrap.style.height = '120px';
        previewWrap.style.background = 'var(--sv-bg-viewport)';
        previewWrap.style.border = '1px solid var(--sv-border)';
        previewWrap.style.borderRadius = 'var(--sv-radius)';
        previewWrap.style.overflow = 'hidden';
        previewWrap.style.flexShrink = '0';
        previewWrap.style.display = 'none'; // Hidden until a region is selected
        previewWrap.id = 'sv-atlas-preview-wrap';
        this.previewCanvas = document.createElement('canvas');
        this.previewCanvas.style.width = '100%';
        this.previewCanvas.style.height = '100%';
        previewWrap.appendChild(this.previewCanvas);
        this.previewCtx = this.previewCanvas.getContext('2d')!;
        this.element.appendChild(previewWrap);

        // Detail panel (shown when a region is selected)
        this.detailPanel = document.createElement('div');
        this.detailPanel.className = 'sv-detail-panel';
        this.detailPanel.style.flexShrink = '0';
        this.element.appendChild(this.detailPanel);

        // Project selector (compare mode only)
        this.projectSelectorRow = document.createElement('div');
        this.projectSelectorRow.style.cssText = 'display:none;align-items:center;gap:6px;padding:4px 0';
        const projectSelectorLabel = document.createElement('span');
        projectSelectorLabel.style.cssText = 'font-size:var(--sv-font-size-sm);color:var(--sv-text-muted);white-space:nowrap';
        projectSelectorLabel.textContent = 'Project:';
        this.projectSelectorRow.appendChild(projectSelectorLabel);
        this.projectSelector = document.createElement('select');
        this.projectSelector.className = 'sv-select';
        this.projectSelector.style.flex = '1';
        this.projectSelector.addEventListener('change', () => {
            const name = this.projectSelector.value;
            const entry = this.compareAtlases.get(name);
            if (entry) {
                this.activeAtlasProject = name;
                this.usedRegionNames = new Set();
                this.setAtlasData(entry.atlas, entry.textures);
            }
        });
        this.projectSelectorRow.appendChild(this.projectSelector);
        this.element.appendChild(this.projectSelectorRow);

        // Compare diff section (compare mode only)
        this.compareSection = document.createElement('div');
        this.compareSection.style.display = 'none';
        this.compareSection.style.marginBottom = '4px';

        const compareHeader = document.createElement('div');
        compareHeader.style.cssText = 'cursor:pointer;font-size:10px;color:var(--sv-text-muted);font-weight:600;letter-spacing:0.4px;padding:4px 0;display:flex;align-items:center;gap:4px';
        const compareArrow = document.createElement('span');
        compareArrow.className = 'sv-section-arrow';
        compareArrow.textContent = '▼';
        compareHeader.appendChild(compareArrow);
        compareHeader.appendChild(Object.assign(document.createElement('span'), { textContent: 'ATLAS COMPARE' }));
        compareHeader.addEventListener('click', () => {
            const collapsed = compareHeader.classList.toggle('collapsed');
            compareArrow.style.transform = collapsed ? 'rotate(-90deg)' : '';
            this.compareSectionBody.style.display = collapsed ? 'none' : 'block';
        });
        this.compareSection.appendChild(compareHeader);

        this.compareSectionBody = document.createElement('div');
        this.compareSection.appendChild(this.compareSectionBody);
        this.element.appendChild(this.compareSection);

        // Search + unused filter row
        const filterRow = document.createElement('div');
        filterRow.style.cssText = 'display:flex;gap:4px;align-items:center;margin:4px 0';
        this.searchInput = document.createElement('input');
        this.searchInput.className = 'sv-tree-search';
        this.searchInput.placeholder = 'Filter regions...';
        this.searchInput.style.flex = '1';
        this.searchInput.style.margin = '0';
        this.searchInput.addEventListener('input', () => this.renderRegionList());
        filterRow.appendChild(this.searchInput);

        this.unusedFilterBtn = document.createElement('button');
        this.unusedFilterBtn.className = 'sv-btn sv-btn-sm';
        this.unusedFilterBtn.textContent = 'Unused';
        this.unusedFilterBtn.title = 'Show only unused atlas regions';
        this.unusedFilterBtn.style.cssText = 'flex-shrink:0;display:none';
        this.unusedFilterBtn.addEventListener('click', () => {
            this.showUnusedOnly = !this.showUnusedOnly;
            this.unusedFilterBtn.classList.toggle('sv-btn-active', this.showUnusedOnly);
            this.renderRegionList();
        });
        filterRow.appendChild(this.unusedFilterBtn);
        this.element.appendChild(filterRow);

        // View full atlas button
        const viewBtn = document.createElement('button');
        viewBtn.className = 'sv-btn sv-btn-sm';
        viewBtn.textContent = 'View Full Atlas';
        viewBtn.style.width = '100%';
        viewBtn.style.justifyContent = 'center';
        viewBtn.style.marginBottom = '4px';
        viewBtn.addEventListener('click', () => this.openAtlasViewer());
        this.element.appendChild(viewBtn);

        // Region list
        this.regionList = document.createElement('div');
        this.regionList.style.flex = '1';
        this.regionList.style.overflowY = 'auto';
        this.regionList.style.minHeight = '0';
        this.element.appendChild(this.regionList);
    }

    setAtlasData(atlas: ParsedAtlas, textures: SpineFileSet['textures']): void {
        this.atlasData = atlas;
        this.textureImages.clear();
        this.selectedRegion = null;

        // Load texture images
        textures.forEach(tex => {
            const img = new Image();
            img.src = tex.data;
            this.textureImages.set(tex.name, img);
        });

        this.renderStats();
        this.renderRegionList();
    }

    private renderStats(): void {
        this.statsPanel.innerHTML = '';
        if (!this.atlasData) return;

        const { pages, regions } = this.atlasData;

        // Calculate total texture area
        let totalPixels = 0;
        let usedPixels = 0;
        pages.forEach(p => { totalPixels += p.width * p.height; });
        regions.forEach(r => { usedPixels += r.width * r.height; });
        const packing = totalPixels > 0 ? Math.round((usedPixels / totalPixels) * 100) : 0;

        // Count rotated regions
        const rotated = regions.filter(r => r.rotate).length;

        // Find size extremes
        const areas = regions.map(r => r.width * r.height);
        const largest = areas.length > 0 ? Math.max(...areas) : 0;
        const smallest = areas.length > 0 ? Math.min(...areas) : 0;

        // Stats grid
        const grid = document.createElement('div');
        grid.className = 'sv-atlas-stats';

        const stats: [string, string][] = [
            ['Pages', String(pages.length)],
            ['Regions', String(regions.length)],
            ['Packing', `${packing}%`],
            ['Rotated', String(rotated)],
        ];

        // Usage stats
        const unusedCount = this.usedRegionNames.size > 0
            ? regions.filter(r => !this.usedRegionNames.has(r.name)).length
            : 0;
        const hasUsageData = this.usedRegionNames.size > 0;
        if (hasUsageData) {
            stats.push(['Unused', String(unusedCount)]);
        }
        // Show/hide unused filter button
        this.unusedFilterBtn.style.display = hasUsageData && unusedCount > 0 ? '' : 'none';
        if (!hasUsageData || unusedCount === 0) {
            this.showUnusedOnly = false;
            this.unusedFilterBtn.classList.remove('sv-btn-active');
        }

        stats.forEach(([label, value]) => {
            const cell = document.createElement('div');
            cell.className = 'sv-atlas-stat';
            const valEl = document.createElement('div');
            valEl.className = 'sv-atlas-stat-value';
            valEl.textContent = value;
            cell.appendChild(valEl);
            const lblEl = document.createElement('div');
            lblEl.className = 'sv-atlas-stat-label';
            lblEl.textContent = label;
            cell.appendChild(lblEl);
            grid.appendChild(cell);
        });

        this.statsPanel.appendChild(grid);

        // Page info
        pages.forEach(page => {
            const pageRegions = regions.filter(r => r.page === page.name);
            const pageUsed = pageRegions.reduce((sum, r) => sum + r.width * r.height, 0);
            const pagePct = page.width * page.height > 0 ? Math.round((pageUsed / (page.width * page.height)) * 100) : 0;

            const row = document.createElement('div');
            row.style.cssText = 'display:flex;align-items:center;gap:6px;padding:3px 0;font-size:var(--sv-font-size-sm);color:var(--sv-text-secondary)';
            row.innerHTML = `<span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${page.name}">${page.name}</span>` +
                `<span style="font-family:var(--sv-font-mono);color:var(--sv-text-muted)">${page.width}\u00D7${page.height}</span>` +
                `<span style="font-family:var(--sv-font-mono)">${pageRegions.length} rgn</span>` +
                `<span style="font-family:var(--sv-font-mono);color:${pagePct > 80 ? 'var(--sv-success)' : pagePct > 50 ? 'var(--sv-warning)' : 'var(--sv-error)'}">${pagePct}%</span>`;
            this.statsPanel.appendChild(row);
        });
    }

    private renderRegionList(): void {
        this.regionList.innerHTML = '';
        if (!this.atlasData) return;

        const filter = this.searchInput.value.toLowerCase();
        let regions = filter
            ? this.atlasData.regions.filter(r => r.name.toLowerCase().includes(filter))
            : this.atlasData.regions;
        if (this.showUnusedOnly && this.usedRegionNames.size > 0) {
            regions = regions.filter(r => !this.usedRegionNames.has(r.name));
        }

        // Group by page
        const byPage = new Map<string, AtlasRegion[]>();
        regions.forEach(r => {
            if (!byPage.has(r.page)) byPage.set(r.page, []);
            byPage.get(r.page)!.push(r);
        });

        byPage.forEach((pageRegions, pageName) => {
            // Page header
            const pageHeader = document.createElement('div');
            pageHeader.className = 'sv-atlas-page-header';
            const arrow = document.createElement('span');
            arrow.className = 'sv-section-arrow';
            arrow.textContent = '\u25BC';
            pageHeader.appendChild(arrow);
            const nameEl = document.createElement('span');
            nameEl.style.flex = '1';
            nameEl.textContent = pageName;
            pageHeader.appendChild(nameEl);
            const badge = document.createElement('span');
            badge.style.cssText = 'font-size:10px;color:var(--sv-text-muted);font-family:var(--sv-font-mono)';
            badge.textContent = String(pageRegions.length);
            pageHeader.appendChild(badge);

            let collapsed = false;
            pageHeader.addEventListener('click', () => {
                collapsed = !collapsed;
                arrow.style.transform = collapsed ? 'rotate(-90deg)' : '';
                pageBody.style.display = collapsed ? 'none' : 'block';
            });
            this.regionList.appendChild(pageHeader);

            const pageBody = document.createElement('div');

            pageRegions.forEach(region => {
                const row = document.createElement('div');
                row.className = 'sv-atlas-region-row';
                if (this.selectedRegion === region) row.classList.add('selected');

                if (this.usedRegionNames.size > 0) {
                    const isUsed = this.usedRegionNames.has(region.name);
                    const dot = document.createElement('span');
                    dot.style.cssText = `width:6px;height:6px;border-radius:50%;flex-shrink:0;background:${isUsed ? 'var(--sv-success)' : 'var(--sv-error)'}`;
                    dot.title = isUsed ? 'Used in project' : 'Not used in any skin or animation';
                    row.appendChild(dot);
                    if (!isUsed) row.style.opacity = '0.55';
                }

                const name = document.createElement('span');
                name.style.cssText = 'flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap';
                name.textContent = region.name;
                row.appendChild(name);

                const size = document.createElement('span');
                size.style.cssText = 'font-size:10px;color:var(--sv-text-muted);font-family:var(--sv-font-mono);flex-shrink:0';
                size.textContent = `${region.width}\u00D7${region.height}`;
                if (region.rotate) size.textContent += ' R';
                row.appendChild(size);

                row.addEventListener('click', () => {
                    this.selectRegion(region);
                    this.regionList.querySelectorAll('.sv-atlas-region-row.selected').forEach(el => el.classList.remove('selected'));
                    row.classList.add('selected');
                });

                pageBody.appendChild(row);
            });

            this.regionList.appendChild(pageBody);
        });
    }

    private selectRegion(region: AtlasRegion): void {
        this.selectedRegion = region;

        // Show preview
        const previewWrap = document.getElementById('sv-atlas-preview-wrap');
        if (previewWrap) previewWrap.style.display = 'block';

        // Update detail panel
        this.detailPanel.innerHTML = '';
        const details: [string, string][] = [
            ['Name', region.name],
            ['Page', region.page],
            ['Position', `${region.x}, ${region.y}`],
            ['Size', `${region.width} \u00D7 ${region.height}`],
            ['Original', `${region.originalWidth} \u00D7 ${region.originalHeight}`],
            ['Offset', `${region.offsetX}, ${region.offsetY}`],
            ['Rotate', String(region.rotate)],
        ];
        details.forEach(([key, value]) => {
            const row = document.createElement('div');
            row.className = 'sv-detail-row';
            const keyEl = document.createElement('span');
            keyEl.className = 'sv-detail-key';
            keyEl.textContent = key;
            row.appendChild(keyEl);
            const valEl = document.createElement('span');
            valEl.className = 'sv-detail-value';
            valEl.textContent = value;
            row.appendChild(valEl);
            this.detailPanel.appendChild(row);
        });

        this.drawPreview(region);
    }

    private openAtlasViewer(): void {
        if (!this.atlasData || this.textureImages.size === 0) return;

        const overlay = document.createElement('div');
        overlay.style.cssText = 'position:fixed;inset:0;z-index:10000;background:rgba(0,0,0,0.85);display:flex;align-items:center;justify-content:center';

        const box = document.createElement('div');
        box.style.cssText = 'background:var(--sv-bg-surface);border:1px solid var(--sv-border);border-radius:var(--sv-radius-lg);padding:12px;display:flex;flex-direction:column;gap:6px;max-width:90vw;max-height:90vh';

        // Title + close
        const titleRow = document.createElement('div');
        titleRow.style.cssText = 'display:flex;align-items:center;gap:8px';
        const title = document.createElement('span');
        title.style.cssText = 'font-weight:600;flex:1;font-size:13px';
        title.textContent = 'Atlas Viewer';
        titleRow.appendChild(title);

        // Page selector if multiple pages
        if (this.atlasData.pages.length > 1) {
            const pageSelect = document.createElement('select');
            pageSelect.className = 'sv-select';
            this.atlasData.pages.forEach(p => {
                const opt = document.createElement('option');
                opt.value = p.name;
                opt.textContent = p.name;
                pageSelect.appendChild(opt);
            });
            pageSelect.addEventListener('change', () => drawPage(pageSelect.value));
            titleRow.appendChild(pageSelect);
        }

        const closeBtn = document.createElement('button');
        closeBtn.className = 'sv-btn sv-btn-sm';
        closeBtn.textContent = '\u00D7';
        closeBtn.addEventListener('click', () => overlay.remove());
        titleRow.appendChild(closeBtn);
        box.appendChild(titleRow);

        // Info row
        const infoEl = document.createElement('div');
        infoEl.style.cssText = 'font-size:var(--sv-font-size-sm);color:var(--sv-text-muted)';
        box.appendChild(infoEl);

        // Canvas
        const canvasWrap = document.createElement('div');
        canvasWrap.style.cssText = 'overflow:auto;flex:1;cursor:crosshair';
        const canvas = document.createElement('canvas');
        canvas.style.cssText = 'display:block;image-rendering:pixelated';
        canvasWrap.appendChild(canvas);
        box.appendChild(canvasWrap);

        const drawPage = (pageName: string) => {
            const page = this.atlasData!.pages.find(p => p.name === pageName);
            if (!page) return;
            const img = this.textureImages.get(page.name);
            if (!img || !img.complete) return;

            canvas.width = img.naturalWidth || page.width;
            canvas.height = img.naturalHeight || page.height;
            const ctx = canvas.getContext('2d')!;

            // Checkerboard
            const cs = 16;
            for (let y = 0; y < canvas.height; y += cs) {
                for (let x = 0; x < canvas.width; x += cs) {
                    ctx.fillStyle = ((x / cs + y / cs) % 2 === 0) ? '#333' : '#3a3a3a';
                    ctx.fillRect(x, y, cs, cs);
                }
            }

            ctx.drawImage(img, 0, 0);

            // Draw region outlines
            const regions = this.atlasData!.regions.filter(r => r.page === pageName);
            ctx.strokeStyle = 'rgba(138,180,248,0.6)';
            ctx.lineWidth = 1;
            regions.forEach(r => {
                ctx.strokeRect(r.x + 0.5, r.y + 0.5, r.width, r.height);
            });

            infoEl.textContent = `${page.name} \u2014 ${canvas.width}\u00D7${canvas.height}px \u2014 ${regions.length} regions`;

            // Hover tooltip
            canvas.onmousemove = (e) => {
                const rect = canvas.getBoundingClientRect();
                const scaleX = canvas.width / rect.width;
                const scaleY = canvas.height / rect.height;
                const mx = (e.clientX - rect.left) * scaleX;
                const my = (e.clientY - rect.top) * scaleY;
                const hit = regions.find(r => mx >= r.x && mx <= r.x + r.width && my >= r.y && my <= r.y + r.height);
                canvas.title = hit ? `${hit.name} (${hit.width}\u00D7${hit.height})` : '';
            };
        };

        // Scale canvas to fit
        canvas.style.maxWidth = 'min(80vw, 900px)';
        canvas.style.maxHeight = 'calc(90vh - 100px)';
        canvas.style.width = 'auto';
        canvas.style.height = 'auto';

        overlay.appendChild(box);
        document.body.appendChild(overlay);
        overlay.addEventListener('click', (e) => { if (e.target === overlay) overlay.remove(); });

        // Draw first page after images may load
        const firstPage = this.atlasData.pages[0];
        const firstImg = this.textureImages.get(firstPage.name);
        if (firstImg?.complete) {
            drawPage(firstPage.name);
        } else if (firstImg) {
            firstImg.onload = () => drawPage(firstPage.name);
        }
    }

    private renderAtlasDiff(): void {
        this.compareSectionBody.innerHTML = '';
        if (this.compareAtlases.size < 2) {
            this.compareSection.style.display = 'none';
            return;
        }
        this.compareSection.style.display = 'block';

        const entries = [...this.compareAtlases.entries()];
        const [nameA, dataA] = entries[0];
        const [nameB, dataB] = entries[1];
        const regionsA = new Set(dataA.atlas.regions.map(r => r.name));
        const regionsB = new Set(dataB.atlas.regions.map(r => r.name));

        const onlyA = dataA.atlas.regions.filter(r => !regionsB.has(r.name));
        const onlyB = dataB.atlas.regions.filter(r => !regionsA.has(r.name));
        const shared = dataA.atlas.regions.filter(r => regionsB.has(r.name));

        // Summary row
        const summary = document.createElement('div');
        summary.style.cssText = 'display:grid;grid-template-columns:1fr 1fr 1fr;gap:4px;padding:4px 0;font-size:10px';
        ([
            [nameA, `${dataA.atlas.regions.length} rgn`],
            ['Shared', `${shared.length}`],
            [nameB, `${dataB.atlas.regions.length} rgn`],
        ] as [string, string][]).forEach(([label, value]) => {
            const cell = document.createElement('div');
            cell.style.cssText = 'text-align:center';
            const v = document.createElement('div');
            v.style.cssText = 'font-weight:600;font-family:var(--sv-font-mono)';
            v.textContent = value;
            const l = document.createElement('div');
            l.style.cssText = 'color:var(--sv-text-muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap';
            l.textContent = label;
            l.title = label;
            cell.appendChild(v);
            cell.appendChild(l);
            summary.appendChild(cell);
        });
        this.compareSectionBody.appendChild(summary);

        const renderGroup = (title: string, regions: Array<{ name: string; width: number; height: number }>, color: string) => {
            if (regions.length === 0) return;
            const hdr = document.createElement('div');
            hdr.style.cssText = `font-size:10px;font-weight:600;padding:4px 0 2px;color:${color}`;
            hdr.textContent = `${title} (${regions.length})`;
            this.compareSectionBody.appendChild(hdr);
            const maxShow = 8;
            regions.slice(0, maxShow).forEach(r => {
                const row = document.createElement('div');
                row.style.cssText = 'display:flex;gap:4px;font-size:10px;padding:1px 0';
                const name = document.createElement('span');
                name.style.cssText = 'flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--sv-text-secondary)';
                name.textContent = r.name;
                name.title = r.name;
                const size = document.createElement('span');
                size.style.cssText = 'color:var(--sv-text-muted);font-family:var(--sv-font-mono);flex-shrink:0';
                size.textContent = `${r.width}×${r.height}`;
                row.appendChild(name);
                row.appendChild(size);
                this.compareSectionBody.appendChild(row);
            });
            if (regions.length > maxShow) {
                const more = document.createElement('div');
                more.style.cssText = 'font-size:10px;color:var(--sv-text-muted);padding:1px 0';
                more.textContent = `…and ${regions.length - maxShow} more`;
                this.compareSectionBody.appendChild(more);
            }
        };

        renderGroup(`Only in ${nameA}`, onlyA, 'var(--sv-diff-only-a, #5ba3f5)');
        renderGroup(`Only in ${nameB}`, onlyB, 'var(--sv-diff-only-b, #f5955b)');
    }

    private drawPreview(region: AtlasRegion): void {
        const img = this.textureImages.get(region.page);
        if (!img) return;

        const canvas = this.previewCanvas;
        const ctx = this.previewCtx;
        canvas.width = canvas.parentElement!.clientWidth || 240;
        canvas.height = canvas.parentElement!.clientHeight || 120;

        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // Draw checkerboard (dark)
        const checkSize = 8;
        for (let y = 0; y < canvas.height; y += checkSize) {
            for (let x = 0; x < canvas.width; x += checkSize) {
                ctx.fillStyle = ((x / checkSize + y / checkSize) % 2 === 0) ? '#2a2a2a' : '#333';
                ctx.fillRect(x, y, checkSize, checkSize);
            }
        }

        // Draw region centered
        const scale = Math.min(
            (canvas.width - 16) / region.width,
            (canvas.height - 16) / region.height,
            2
        );
        const drawW = region.width * scale;
        const drawH = region.height * scale;
        const drawX = (canvas.width - drawW) / 2;
        const drawY = (canvas.height - drawH) / 2;

        if (img.complete) {
            ctx.drawImage(
                img,
                region.x, region.y, region.width, region.height,
                drawX, drawY, drawW, drawH
            );
        } else {
            img.onload = () => this.drawPreview(region);
        }
    }
}
